 const labels={film_bundle:'Dossier film',film_animatic:'Animatique du film',scenario:'Scénario',decoupage:'Découpage',video_script:'Script vidéo · ElevenLabs',storyboard:'Storyboard',animatic:'Animatique',motion:'Titre animé',graphic:'Carte / graphique',three_d:'Pack 3D',color:'Pack étalonnage',vfx:'Élément VFX',transition:'Transition',ps_motion:'Texte Photoshop animé',photoshop:'Texte Photoshop',tts:'Voix',asr:'Transcription',ocr:'Lecture de document',sound:'Banque sonore',music:'Musique'};
async function api(url,body){const headers={'X-Studio-Token':boot?.token||''};const opts={headers};if(body!==undefined){opts.method='POST';headers['Content-Type']='application/json';opts.body=JSON.stringify(body)}const r=await fetch(url,opts);const d=await r.json();if(!r.ok)throw Error(typeof d.detail==='string'?d.detail:JSON.stringify(d.detail));return d;}
function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',7000)}
async function authCall(path,body){const r=await fetch(path,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});const d=await r.json();if(!r.ok)throw Error(d.detail||'Connexion impossible');return d}
function authView(){
 const setup=boot?.auth?.requires_setup;$('#section-name').textContent='Accès sécurisé';
 $('#workspace').innerHTML=`<div class="auth-shell"><div class="auth-mark">R<span>·</span></div><div class="eyebrow">RÉVÉLATION AI STUDIO</div><h1>${setup?'Créer le profil réalisateur':'Ouvrir le studio'}</h1><p class="intro">${setup?'Le mot de passe reste local sous forme de hash scrypt renforcé. Il protège les projets, les modèles et les productions du poste.':'Le Studio redemande le mot de passe après un redémarrage. Aucun secret de fournisseur n’est affiché dans cette page.'}</p><div class="card card-pad auth-card">${setup?field('Identité enregistrée','<input id="auth-identity" maxlength="120" placeholder="Nom du réalisateur / studio">'):''}${field('Mot de passe',`<input id="auth-password" type="password" minlength="${setup?12:1}" autocomplete="new-password" placeholder="${setup?'12 caractères minimum':'Mot de passe local'}">`)}${setup?field('Confirmer le mot de passe','<input id="auth-confirm" type="password" minlength="12" autocomplete="new-password">'):''}<button class="primary" id="auth-submit">${setup?'Créer et ouvrir le Studio':'Se connecter'} <span style="float:right">↗</span></button><p class="hint">${setup?'Choisir au moins 12 caractères. La session expire après une période d’inactivité et cinq échecs rapprochés déclenchent un verrouillage temporaire.':'Le Studio reste sur 127.0.0.1. En cas d’oubli, utiliser la procédure locale de récupération documentée dans LIRE_MOI.md.'}</p></div></div>`;
 $('#auth-submit').onclick=async()=>{try{const password=$('#auth-password').value;if(setup&&password.length<12)throw Error('Le mot de passe doit contenir au moins 12 caractères.');if(setup&&password!==$('#auth-confirm').value)throw Error('Les deux mots de passe ne correspondent pas.');const d=await authCall(setup?'/api/auth/setup':'/api/auth/login',{identity:setup?$('#auth-identity').value.trim():'',password});boot.token=d.token;await bootSession()}catch(e){toast(e.message)}};
}
async function bootSession(){boot=await api('/api/bootstrap');if(!boot.auth?.authenticated){authView();return}await refresh();allJobs=await api('/api/jobs');render();startPolling();if(window.StudioReturn)await StudioReturn.openFromURL();}
function navigate(id){if(page==='film'&&typeof filmCapture==='function')filmCapture();if(page==='motion')saveMotionDraft();if(page==='montage'&&id!=='montage'&&window.StudioEditor)StudioEditor.unmount();page=id;uploaded=[];render();}
function nav(){ $('#nav').innerHTML=pages.map(([id,ico,name])=>`${navGroups[id]?`<div class="nav-group">${navGroups[id]}</div>`:''}<button class="nav-item ${page===id?'active':''}" data-page="${id}" title="${name}"><span>${ico}</span><em style="font-style:normal">${name}</em></button>`).join('');document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>navigate(b.dataset.page));$('#section-name').textContent=pages.find(p=>p[0]===page)[2];}
function head(k,title,desc,right=''){return `<div class="page-head"><div><div class="eyebrow">${k}</div><h1>${title}</h1><p class="intro">${desc}</p></div>${right}</div>`}
function field(label,html){const id=html.match(/\bid="([^"]+)"/);return `<div class="field"><label ${id?`for="${esc(id[1])}"`:''}>${label}</label>${html}</div>`}
function familyLabel(value){return ({agent:'Agents IA',workflow_local:'Workflow local',image_local:'Image local',image_3d_audio:'Image · 3D · audio',video_local:'Vidéo locale',audio_local:'Audio local',musique_local:'Musique locale',motion_design:'Motion design',voix_son:'Voix · son',capture_animation:'Capture · animation',avatar_doublage:'Avatar · doublage',postproduction:'Postproduction',restauration:'Restauration',transcription:'Transcription',musique:'Musique',video:'Vidéo',image:'Image','3d':'3D'}[value]||String(value||'production').replaceAll('_',' '))}
function modelSelect(kind='text'){const m=stats.models.filter(m=>m.kind===kind).sort((a,b)=>Number(b.id==='ollama:qwen2.5-coder:1.5b')-Number(a.id==='ollama:qwen2.5-coder:1.5b'));return `<select id="model">${!m.some(x=>x.can_run)?'<option value="">Configurer un moteur dans IA & quotas</option>':''}${m.map(m=>`<option value="${esc(m.id)}" ${!m.can_run?'disabled':''}>${esc(m.name)}${!m.can_run?' · à configurer':''}</option>`).join('')}</select>`;}
function timing(seconds=5){return `<div class="row">${field('Durée (secondes)',`<input id="seconds" type="number" min="3" max="120" value="${seconds}">`)}${field('Cadence',`<select id="fps"><option value="25">25 images/s</option><option value="24">24 images/s</option><option value="30">30 images/s</option></select>`)}</div>`}
function uploadBox(two=false){return `<label class="upload"><span>＋ ${two?'Ajouter deux plans vidéo':'Ajouter un fichier local'}</span><input id="upload" type="file" ${two?'multiple accept="video/*"':'accept="audio/*,video/*,image/*"'}></label><div id="uploads" class="upload-list"></div>`;}
function action(label='Générer le pack'){return `<button class="primary" id="generate">${label} <span style="float:right">↗</span></button><p class="hint">Sources modifiables et fichiers de contrôle conservés. Destination : ${stats.external_mounted?'Samsung T7':'stockage local du Studio'}.</p>`}
function jobArea(){return `<section class="section-space"><div class="small-head">PRODUCTIONS RÉCENTES</div><div id="jobs" class="job-list"></div></section>`}
function parseSceneLines(value){return value.split('\n').map(x=>x.trim()).filter(Boolean).map((line,i)=>{const a=line.split('|').map(x=>x.trim());return {id:`scene-${String(i+1).padStart(2,'0')}`,number:i+1,title:a[0]||`Scène ${i+1}`,action:a[1]||'',dialogue_source:a[2]||'',image_prompt:a[3]||'',characters:[],shot_list:[]}})}
