 if(page==='montage'){if(window.StudioEditor)window.StudioEditor.mount(w);else w.innerHTML='<div class="card card-pad"><h2>Montage indisponible</h2><p class="intro">Le module editor.js n’a pas été chargé. Recharge la page.</p></div>';return}
