function renderJobs(){const signature=JSON.stringify([page,allJobs]);if($('#jobs').dataset.signature===signature)return;$('#jobs').dataset.signature=signature;const relevant=allJobs.filter(j=>page==='film'?['film_bundle','film_animatic','scenario','decoupage'].includes(j.spec.kind)&&j.spec.project_id===filmState.pid:page==='motion'?j.spec.kind.startsWith('motion'):page==='photoshop'?j.spec.kind.startsWith('photoshop')||j.spec.kind==='ps_motion':page==='scenario'?['scenario','decoupage'].includes(j.spec.kind):page==='storyboard'?['storyboard','animatic'].includes(j.spec.kind):page==='project'?['scenario','decoupage','storyboard','animatic'].includes(j.spec.kind):page==='graphics'?j.spec.kind==='graphic':page==='three_d'?j.spec.kind==='three_d':page==='color'?j.spec.kind.startsWith('color'):page==='effects'?['transition','vfx','transition_advice','vfx_advice'].includes(j.spec.kind):page==='audio'?['tts','asr','ocr','sound','music'].includes(j.spec.kind):[]);$('#jobs').innerHTML=relevant.slice(0,8).map(j=>{const done=j.status==='complete',running=['running','queued'].includes(j.status),state={complete:'Terminé',running:'Traitement en cours',queued:'En attente',failed:'À corriger',cancelled:'Annulé',interrupted:'Interrompu'}[j.status]||j.status;const filelist=j.files.filter(f=>!['DEMANDE_ORIGINALE.json','REQUETE_MODELE.json','CHARTE_CINEMA.txt','REFERENCES.json','moteur.log','rendu.log','MODELE_EXECUTE.json'].includes(f.name));return `<article class="job"><div class="job-head"><div class="job-title">${esc(labels[j.spec.kind]||j.spec.kind)} · ${esc(j.spec.title)}<small>${new Date(j.created_at).toLocaleString('fr-FR',{timeZone:'Africa/Abidjan'})} · ${esc(j.id)}</small></div><span class="badge ${done?'ok':running?'busy':'fail'}">${state}</span></div>${running?`<div class="bar"><div style="width:${j.progress||2}%"></div></div>`:''}<div class="job-body">${j.spec.film_snapshot?`<p class="${page==='film'&&j.spec.film_snapshot.revision!==filmState.data?.project.revision?'warn-note':'hint'}">Produit depuis la version ${j.spec.film_snapshot.revision??0} du projet${page==='film'&&j.spec.film_snapshot.revision!==filmState.data?.project.revision?' · une autre version est actuellement chargée.':'.'}</p>`:''}${j.error?`<div class="job-error">${esc(j.error)}</div>`:''}${j.text?`<details ${j.id===activeJob?'open':''}><summary class="text-link">Lire la proposition</summary><pre class="job-text">${esc(j.text)}</pre></details>`:''}${done?`${j.files.some(f=>['APERCU_MOTION.mp4','APERCU_MOTION.webm','FILM_ANIMATIQUE.mp4','FILM_ANIMATIQUE.webm'].includes(f.name))?`<video class="motion-player" controls preload="metadata" ${j.files.some(f=>f.name==='apercu.jpg')?`poster="${jobPreviewURL(j,'apercu.jpg')}"`:''} src="${jobPreviewURL(j,j.files.find(f=>['APERCU_MOTION.mp4','APERCU_MOTION.webm','FILM_ANIMATIQUE.mp4','FILM_ANIMATIQUE.webm'].includes(f.name))?.name)}"></video>`:''}<div class="files">${filelist.map(f=>`<a class="file" href="${f.url}" download>${esc(f.name)} ↧</a>`).join('')}</div><div class="send-row">${['film_animatic','motion','ps_motion','graphic','three_d','vfx','transition','tts','sound','animatic'].includes(j.spec.kind)?`<button class="secondary send" data-id="${j.id}" data-target="resolve">Envoyer à Resolve</button><button class="secondary send" data-id="${j.id}" data-target="premiere">Envoyer à Premiere</button>${j.spec.kind==='three_d'?`<button class="secondary send" data-id="${j.id}" data-target="blender">Ouvrir dans Blender</button>`:''}`:''}${['motion','ps_motion'].includes(j.spec.kind)?`<button class="secondary send" data-id="${j.id}" data-target="after_effects">Composition After Effects</button>`:''}${j.spec.kind==='photoshop'?`<button class="secondary send" data-id="${j.id}" data-target="photoshop">Créer dans Photoshop</button>`:''}<button class="secondary reveal" data-id="${j.id}">Voir le dossier</button></div>`:''}${running?`<button class="secondary cancel" data-id="${j.id}">Annuler le traitement</button>`:''}</div></article>`}).join('')||'<div class="empty">Tes productions apparaîtront ici avec leurs fichiers et leur état réel.</div>';document.querySelectorAll('.send').forEach(b=>b.onclick=async()=>{b.disabled=true;try{const d=await api('/api/jobs/'+b.dataset.id+'/send',{target:b.dataset.target});toast(d.message||'Envoi confirmé par le logiciel.')}catch(e){toast(e.message)}finally{b.disabled=false}});document.querySelectorAll('.cancel').forEach(b=>b.onclick=async()=>{try{await api('/api/jobs/'+b.dataset.id+'/cancel',{});toast('Annulation demandée.')}catch(e){toast(e.message)}});if(window.webkit?.messageHandlers?.studio)document.querySelectorAll('#jobs .file').forEach(a=>a.onclick=e=>{e.preventDefault();const u=new URL(a.href),parts=u.pathname.split('/');api('/api/jobs/'+parts[3]+'/open',{filename:decodeURIComponent(parts[4])}).catch(err=>toast(err.message))});document.querySelectorAll('.reveal').forEach(b=>b.onclick=()=>nativeAction({action:'reveal_job',id:b.dataset.id}));}
